import{H as e,V as t,et as n,j as r}from"./chunks/framework.CGBIEL5E.js";var i=JSON.parse(`{"title":"BLE 数据包格式","description":"","frontmatter":{},"headers":[],"relativePath":"common/ble-packet.md","filePath":"common/ble-packet.md","lastUpdated":1786619375000}`),a={name:`common/ble-packet.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ble-数据包格式" tabindex="-1">BLE 数据包格式 <a class="header-anchor" href="#ble-数据包格式" aria-label="Permalink to “BLE 数据包格式”">​</a></h1><p>本文定义 <strong>AHE01 / AHE02 / AHE03 / AHE04</strong> 与 APP 之间 BLE 通讯的<strong>数据包封装规则</strong>（完整数据包、BLE 传输包、分包、CRC）。四款产品都支持 BLE 与 APP 通讯，格式共用。</p><h2 id="设备架构-四款相同" tabindex="-1">设备架构（四款相同） <a class="header-anchor" href="#设备架构-四款相同" aria-label="Permalink to “设备架构（四款相同）”">​</a></h2><p>每款产品都是 <strong>STM32 主板 + ESP32 网关</strong>：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP  ←—— BLE ——→  ESP32 网关  ←—— UART（SPF）——→  STM32 主板</span></span></code></pre></div><p>APP 只对接 BLE。控制命令路径：APP 写 BLE → 网关转 SPF 给主板 → 主板处理后经 BLE 应答 APP。等应答建议超时 <strong>5 秒</strong>。SPF 帧格式不在本文范围。</p><p>当前控制类命令 <strong>默认单包发送</strong>（完整数据包 ≤ 18 字节，帧头 <code>01 00</code>）。仅超长数据（如睡眠报告）才分包。</p><p>各产品的 <strong>CMD 命令、VALUE 含义、服务特征、业务流程</strong> 以该产品自己的 BLE 协议为准，本文不作为命令字典。</p><ul><li>AHE01 益安枕：<a href="/ahs-docs/products/ahe01/ble-protocol.html">BLE 协议（固件 ≥ V10）</a>、<a href="/ahs-docs/products/ahe01/ble-music.html">本地音乐列表</a></li><li>AHE02 / AHE03 / AHE04：命令表随各产品协议补充</li></ul><h2 id="_1-协议概述" tabindex="-1">1. 协议概述 <a class="header-anchor" href="#_1-协议概述" aria-label="Permalink to “1. 协议概述”">​</a></h2><p>通讯中有两种数据包：</p><ol><li><strong>完整数据包</strong>：不含包头的逻辑数据包，长度可超过 18 字节</li><li><strong>BLE 传输包</strong>：实际走空中的物理包，最大 20 字节，带包头</li></ol><h2 id="_2-数据包定义" tabindex="-1">2. 数据包定义 <a class="header-anchor" href="#_2-数据包定义" aria-label="Permalink to “2. 数据包定义”">​</a></h2><h3 id="_2-1-完整数据包-逻辑数据包" tabindex="-1">2.1 完整数据包（逻辑数据包） <a class="header-anchor" href="#_2-1-完整数据包-逻辑数据包" aria-label="Permalink to “2.1 完整数据包（逻辑数据包）”">​</a></h3><p>完整数据包是协议的核心结构，不含包头，用来描述一条完整命令。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌────────────┬──────┬────────┬──────────────┬───────┐</span></span>
<span class="line"><span>│ cmd_type   │ cmd  │ length │  value       │ crc8  │</span></span>
<span class="line"><span>│  1 字节    │ 1字节 │ 1 字节 │ length 字节  │ 1 字节 │</span></span>
<span class="line"><span>└────────────┴──────┴────────┴──────────────┴───────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>cmd_type</td><td>1 字节</td><td>命令类型，见第 3 节</td></tr><tr><td>cmd</td><td>1 字节</td><td>具体命令（各产品定义不同）</td></tr><tr><td>length</td><td>1 字节</td><td>value 字段的字节数</td></tr><tr><td>value</td><td>length 字节</td><td>实际数据</td></tr><tr><td>crc8</td><td>1 字节</td><td>校验和，见第 4 节</td></tr></tbody></table><p>完整数据包长度 = 4 + length 字节（可超过 18 字节）。</p><h3 id="_2-2-ble-传输包-物理数据包" tabindex="-1">2.2 BLE 传输包（物理数据包） <a class="header-anchor" href="#_2-2-ble-传输包-物理数据包" aria-label="Permalink to “2.2 BLE 传输包（物理数据包）”">​</a></h3><p>BLE 传输包是实际无线发出的包，最大 20 字节。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────┬─────────────┬──────────────────────────────┐</span></span>
<span class="line"><span>│ package_num │ package_seq │      数据片段                 │</span></span>
<span class="line"><span>│   1 字节    │    1 字节    │   最多 18 字节               │</span></span>
<span class="line"><span>└─────────────┴─────────────┴──────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>package_num</td><td>1 字节</td><td>总包数（完整数据包被拆分后的包数）</td></tr><tr><td>package_seq</td><td>1 字节</td><td>包序号，从 0 开始递增</td></tr><tr><td>数据片段</td><td>最多 18 字节</td><td>完整数据包的一部分或全部</td></tr></tbody></table><p>BLE 传输包长度 = 2 + 数据片段长度（最大 20 字节）。</p><p>单包时帧头固定为 <code>01 00</code>（总包数 1、序号 0）。</p><h2 id="_3-命令类型-cmd-type" tabindex="-1">3. 命令类型（cmd_type） <a class="header-anchor" href="#_3-命令类型-cmd-type" aria-label="Permalink to “3. 命令类型（cmd_type）”">​</a></h2><table tabindex="0"><thead><tr><th>值</th><th>中文名称</th><th>方向</th></tr></thead><tbody><tr><td>0x01</td><td>APP 读设备数据</td><td>APP → 设备</td></tr><tr><td>0x02</td><td>APP 写设备数据</td><td>APP → 设备</td></tr><tr><td>0x11</td><td>设备应答 APP 读数据</td><td>设备 → APP</td></tr><tr><td>0x12</td><td>设备应答 APP 写数据</td><td>设备 → APP</td></tr><tr><td>0x13</td><td>设备主动通知 APP 数据</td><td>设备 → APP</td></tr></tbody></table><p>对应关系：</p><ul><li><strong>APP 写设备数据</strong>（0x02）与 <strong>设备写应答</strong>（0x12）成对</li><li><strong>APP 读设备数据</strong>（0x01）与 <strong>设备读应答</strong>（0x11）成对</li><li><strong>设备主动通知</strong>（0x13）单向，不需要 APP 先发指令</li></ul><p>具体 <code>cmd</code> 见各产品 BLE 协议。下文示例里的命令码只为说明分包，不以示例命令表为准。</p><h2 id="_4-crc8-校验" tabindex="-1">4. CRC8 校验 <a class="header-anchor" href="#_4-crc8-校验" aria-label="Permalink to “4. CRC8 校验”">​</a></h2><p>对完整数据包中 <code>cmd_type</code> 到 <code>value</code> 的所有字节按顺序异或，结果即为 crc8（不含包头 <code>package_num</code> / <code>package_seq</code>）。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>crc8 = cmd_type ⊕ cmd ⊕ length ⊕ value[0] ⊕ value[1] ⊕ ... ⊕ value[length-1]</span></span></code></pre></div><p>接收完整数据包后必须按本文校验 crc8。发送方必须计算并带上。当前网关固件为便于调试可能不校验收到的 CRC，<strong>以本文为准</strong>。部分 APP 若用 <code>0xFF</code> 占位，仅调试期可能仍能通，正式实现不要省略异或。</p><h2 id="_5-通讯场景示例" tabindex="-1">5. 通讯场景示例 <a class="header-anchor" href="#_5-通讯场景示例" aria-label="Permalink to “5. 通讯场景示例”">​</a></h2><p>以下用「WIFI SSID 读写」「读设备编号」等命令码演示封装与分包。这些命令在 AHE01 协议中存在；其它型号若命令码不同，<strong>只替换 cmd / value，封装规则不变</strong>。</p><h3 id="_5-1-app-写设备数据-设备写应答-短包" tabindex="-1">5.1 APP 写设备数据 + 设备写应答（短包） <a class="header-anchor" href="#_5-1-app-写设备数据-设备写应答-短包" aria-label="Permalink to “5.1 APP 写设备数据 + 设备写应答（短包）”">​</a></h3><p>APP 写入 WIFI SSID = <code>AHE01-123456</code>（UTF-8 共 12 字节）。</p><p>APP 构建完整数据包：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────┬──────┬────────┬────────────────────────────────────────┬───────┐</span></span>
<span class="line"><span>│ cmd_type │ cmd  │ length │            value                       │ crc8  │</span></span>
<span class="line"><span>│   0x02   │ 0x72 │  0x0C  │ 41 48 45 30 31 2D 31 32 33 34 35 36    │ 0xXX  │</span></span>
<span class="line"><span>└──────────┴──────┴────────┴────────────────────────────────────────┴───────┘</span></span></code></pre></div><ul><li>cmd_type：APP 写设备数据</li><li>cmd：WIFI SSID 读写</li><li>完整包长度 ≤ 18 字节，单包发送</li></ul><p>APP 发出的 BLE 传输包：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 00 02 72 0C 41 48 45 30 31 2D 31 32 33 34 35 36 crc8</span></span></code></pre></div><p>设备写应答（value <code>0x00</code> 成功，非 0 失败）：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 00 12 72 01 00 1A</span></span></code></pre></div><p>校验：<code>0x12 ⊕ 0x72 ⊕ 0x01 ⊕ 0x00 = 0x1A</code>。</p><h3 id="_5-2-app-读设备数据-设备读应答-短包" tabindex="-1">5.2 APP 读设备数据 + 设备读应答（短包） <a class="header-anchor" href="#_5-2-app-读设备数据-设备读应答-短包" aria-label="Permalink to “5.2 APP 读设备数据 + 设备读应答（短包）”">​</a></h3><p>APP 读取设备编号（读命令无 value）：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>完整包：01 75 00 74</span></span>
<span class="line"><span>CRC：0x01 ⊕ 0x75 ⊕ 0x00 = 0x74</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BLE 传输包：</span></span>
<span class="line"><span>01 00 01 75 00 74</span></span></code></pre></div><p>设备应答设备编号 <code>AHE01-001</code>（UTF-8 9 字节）：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01 00 11 75 09 41 48 45 30 31 2D 30 30 31 crc8</span></span></code></pre></div><p>解码 value 得到字符串 <code>AHE01-001</code>。</p><h3 id="_5-3-app-写设备数据-设备写应答-长包" tabindex="-1">5.3 APP 写设备数据 + 设备写应答（长包） <a class="header-anchor" href="#_5-3-app-写设备数据-设备写应答-长包" aria-label="Permalink to “5.3 APP 写设备数据 + 设备写应答（长包）”">​</a></h3><p>WIFI SSID 较长、完整数据包 &gt; 18 字节时拆成多包：</p><ul><li>每个 BLE 传输包最多带 <strong>18 字节</strong>数据片段</li><li>总包数 = ceil(完整数据包长度 / 18)</li><li>第 1 包 <code>package_seq = 0</code>，其后递增</li></ul><p>示例：完整包 26 字节 → 2 包（18 + 8）。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>第 1 包：02 00 + 前 18 字节数据片段</span></span>
<span class="line"><span>第 2 包：02 01 + 剩余数据片段 + crc8</span></span></code></pre></div><p>设备按序号拼接后再解析完整数据包，并回写应答（通常仍为单包）。</p><h3 id="_5-4-app-读设备数据-设备读应答-长包" tabindex="-1">5.4 APP 读设备数据 + 设备读应答（长包） <a class="header-anchor" href="#_5-4-app-读设备数据-设备读应答-长包" aria-label="Permalink to “5.4 APP 读设备数据 + 设备读应答（长包）”">​</a></h3><p>读命令本身一般是短包；设备读应答若 value 很长，则由设备拆成多包，APP 按 <code>package_num</code> / <code>package_seq</code> 拼接后再校验 crc8。</p><h3 id="_5-5-设备主动通知-短包" tabindex="-1">5.5 设备主动通知（短包） <a class="header-anchor" href="#_5-5-设备主动通知-短包" aria-label="Permalink to “5.5 设备主动通知（短包）”">​</a></h3><p>设备使用 <strong>设备主动通知 APP 数据</strong>（cmd_type = 0x13）上报，无需 APP 先发读命令。</p><p>AHE01 上最常见的是 <strong>实时数据</strong>（cmd = 0x01），详见 <a href="/ahs-docs/products/ahe01/ble-protocol.html">AHE01 BLE 协议</a>。</p><p>APP 须在连接建立后立即打开通知监听。</p><h2 id="_6-数据发送流程" tabindex="-1">6. 数据发送流程 <a class="header-anchor" href="#_6-数据发送流程" aria-label="Permalink to “6. 数据发送流程”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>完整数据包（逻辑层）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    判断长度</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  ≤ 18 字节          &gt; 18 字节</span></span>
<span class="line"><span>    单包传输          多包传输</span></span>
<span class="line"><span>  1 个 BLE 传输包    多个 BLE 传输包</span></span></code></pre></div><p>单包：<code>package_num = 1</code>，<code>package_seq = 0</code>，数据片段 = 整份完整数据包。</p><p>多包：按 18 字节边界拆分，不得拆断后再打乱顺序发送。</p><h2 id="_7-数据接收流程" tabindex="-1">7. 数据接收流程 <a class="header-anchor" href="#_7-数据接收流程" aria-label="Permalink to “7. 数据接收流程”">​</a></h2><ol><li>收到 BLE 传输包，取出 package_num、package_seq、数据片段</li><li>按 package_num 确定总包数</li><li>按 package_seq 从 0 收到 package_num−1</li><li>按序拼接得到完整数据包</li><li>校验 crc8 后解析 cmd_type、cmd、length、value</li></ol><p>乱序包应缓存或丢弃；多包接收应设超时。</p><h2 id="_8-完整数据包-vs-ble-传输包" tabindex="-1">8. 完整数据包 vs BLE 传输包 <a class="header-anchor" href="#_8-完整数据包-vs-ble-传输包" aria-label="Permalink to “8. 完整数据包 vs BLE 传输包”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>完整数据包</th><th>BLE 传输包</th></tr></thead><tbody><tr><td>定义</td><td>逻辑包，一条完整命令</td><td>物理包，真正发出的 BLE 数据</td></tr><tr><td>长度</td><td>无硬性上限</td><td>最大 20 字节</td></tr><tr><td>内容</td><td>cmd_type + cmd + length + value + crc8</td><td>package_num + package_seq + 数据片段</td></tr><tr><td>传输</td><td>需拆成 BLE 传输包</td><td>直接走 BLE</td></tr></tbody></table><h2 id="_9-重要说明" tabindex="-1">9. 重要说明 <a class="header-anchor" href="#_9-重要说明" aria-label="Permalink to “9. 重要说明”">​</a></h2><ol><li>字符串（如 SSID、密码、设备编号）使用 <strong>UTF-8</strong>；中文通常 3 字节一个字。</li><li>多字节字段在产品协议中统一为 <strong>大端</strong>（高字节在前），见各产品 BLE 协议。</li><li>必须按 package_seq 顺序处理；建议实现超时与丢包重传。</li><li>分包严格按 18 字节边界，保证拼回后仍是完整数据包。</li><li>APP 写 / 读之后应等待对应应答，再判断成功与否。</li><li>连接后立刻监听通知，以便接收 <strong>设备主动通知</strong>。</li></ol>`,74)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};